// Modul 2 [PREMIUM]: Simpan Transaksi Kasir ke Google Sheets
function doPost(e) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName('Transaksi');
  const data = JSON.parse(e.postData.contents);

  sheet.appendRow([
    new Date(),
    data.invoiceId,
    data.namaKasir,
    JSON.stringify(data.items),
    data.totalBayar,
    data.metodePembayaran
  ]);

  return ContentService.createTextOutput(JSON.stringify({
    status: 'success',
    message: 'Transaksi berhasil disimpan ke Google Sheets!'
  })).setMimeType(ContentService.MimeType.JSON);
}

// Modul 3 [PREMIUM]: Cetak Struk Thermal 58mm & Rekap Harian
function printThermalReceipt(order) {
  const printWindow = window.open('', '_blank', 'width=320,height=500');
  printWindow.document.write(`
    <html><body style="font-family:monospace;width:58mm;font-size:12px;">
      <center><b>KREASI KOPI NUSANTARA</b><br/>Nota: ${order.invoiceId}</center>
      <hr/>
      ${order.items.map(i => `<div>${i.qty}x ${i.name} - Rp ${i.price * i.qty}</div>`).join('')}
      <hr/>
      <b>TOTAL: Rp ${order.totalBayar.toLocaleString('id-ID')}</b>
    </body></html>
  `);
  printWindow.document.close();
  printWindow.print();
}

// Modul 2 [PREMIUM]: Format Pesanan Otomatis ke WhatsApp Kasir & Google Sheets
function sendOrderToWhatsApp(nomorKasir, namaPelanggan, nomorMeja, items, total) {
  let pesan = `*PESANAN BARU - MEJA ${nomorMeja}*\nPemesan: ${namaPelanggan}\n------------------\n`;
  items.forEach(item => {
    pesan += `• ${item.qty}x ${item.nama} (Rp ${(item.harga * item.qty).toLocaleString('id-ID')})\n`;
  });
  pesan += `------------------\n*TOTAL: Rp ${total.toLocaleString('id-ID')}*`;

  const waUrl = `https://wa.me/${nomorKasir}?text=${encodeURIComponent(pesan)}`;
  window.open(waUrl, '_blank');
}

// Modul 2 [PREMIUM]: Generate PDF CV dari Template Google Docs via Apps Script
function generateCVPdf(formData) {
  const templateId = 'ID_GOOGLE_DOCS_TEMPLATE_ANDA';
  const copyFile = DriveApp.getFileById(templateId).makeCopy('CV_' + formData.nama);
  const doc = DocumentApp.openById(copyFile.getId());
  const body = doc.getBody();

  body.replaceText('{{NAMA_LENGKAP}}', formData.nama);
  body.replaceText('{{POSISI}}', formData.posisi);
  body.replaceText('{{PENGALAMAN}}', formData.pengalaman);
  doc.saveAndClose();

  const pdfBlob = copyFile.getAs(MimeType.PDF);
  const pdfFile = DriveApp.createFile(pdfBlob);
  pdfFile.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
  return pdfFile.getDownloadUrl();
}

// Modul 2 [PREMIUM]: Integrasi html5-qrcode Scanner & Kirim ke Google Sheets
function onScanSuccess(decodedText) {
  fetch('URL_WEB_APP_GOOGLE_APPS_SCRIPT_ANDA', {
    method: 'POST',
    body: JSON.stringify({
      idPeserta: decodedText,
      waktuHadir: new Date().toLocaleString('id-ID'),
      status: 'HADIR TEPAT WAKTU'
    })
  })
  .then(res => res.json())
  .then(data => alert('Absensi Berhasil: ' + decodedText));
}

// Modul 2 [PREMIUM]: Kirim Email HTML + E-Ticket QR Otomatis via MailApp
function sendEventTicket(nama, email, kodeTiket) {
  const qrUrl = 'https://api.qrserver.com/v1/create-qr-code/?size=220x220&data=' + encodeURIComponent(kodeTiket);
  const htmlBody = `
    <div style="font-family:sans-serif;padding:24px;background:#0F172A;color:#fff;border-radius:16px;">
      <h2 style="color:#F59E0B;">E-Ticket Resmi Workshop Kreasi Rupa</h2>
      <p>Halo <b>${nama}</b>, pendaftaranmu telah terkonfirmasi!</p>
      <img src="${qrUrl}" alt="QR Ticket" style="border:6px solid #fff;border-radius:12px;" />
      <p>Kode Tiket: <b>${kodeTiket}</b></p>
    </div>
  `;
  MailApp.sendEmail({
    to: email,
    subject: '[E-TICKET] Konfirmasi Pendaftaran - ' + kodeTiket,
    htmlBody: htmlBody
  });
}

// Modul 1 [FREE TRIAL]: Kalkulasi Bobot Nilai & Predikat Otomatis
function hitungNilaiAkhir(tugas, uts, uas) {
  const nilaiAkhir = (tugas * 0.3) + (uts * 0.3) + (uas * 0.4);
  let predikat = 'C';
  if (nilaiAkhir >= 85) predikat = 'A (Sangat Baik)';
  else if (nilaiAkhir >= 75) predikat = 'B (Baik)';

  return {
    skor: nilaiAkhir.toFixed(1),
    predikat: predikat,
    lulus: nilaiAkhir >= 70
  };
}

